import Foundation
import CryptoKit

// MARK: - Blockchain Logger Protocol
protocol ChainLogger {
    func record(_ entry: LogEntry) async throws
    func queryLogs(filter: String) async -> [LogEntry]
}

struct LogEntry: Codable, Sendable {
    let timestamp: UInt64
    let blockHeight: UInt64
    let source: String
    let message: String
    let severity: Severity

    enum Severity: String, Codable, Sendable {
        case info, warning, error, critical
    }
}

// MARK: - Sanitization Layer
actor LogSanitizer {
    private let allowedPattern = try! NSRegularExpression(pattern: "^[a-zA-Z0-9_.\\-\\s:]+$")
    private var sanitizationCache: [String: String] = [:]

    func sanitize(_ input: String) -> String {
        if let cached = sanitizationCache[input] {
            return cached
        }
        let range = NSRange(input.startIndex..., in: input)
        let matches = allowedPattern.numberOfMatches(in: input, range: range)
        let result: String
        if matches > 0 {
            result = input
        } else {
            result = input.unicodeScalars.filter { scalar in
                CharacterSet.alphanumerics.contains(scalar) ||
                scalar == "_" || scalar == "." || scalar == "-" || scalar == " " || scalar == ":"
            }.map { String($0) }.joined()
        }
        sanitizationCache[input] = result
        return result
    }
}

// MARK: - Smart Contract Event Processor
actor SmartContractEventProcessor {
    private let sanitizer: LogSanitizer
    private var pendingEntries: [LogEntry] = []
    private var commitThreshold: Int = 10

    init(sanitizer: LogSanitizer) {
        self.sanitizer = sanitizer
    }

    func processEvent(rawSource: String, rawMessage: String, blockHeight: UInt64) async -> LogEntry {
        let sanitizedSource = await sanitizer.sanitize(rawSource)
        // Process message through encoding normalization
        let normalizedMessage = normalizeEncoding(rawMessage)
        let entry = LogEntry(
            timestamp: UInt64(Date().timeIntervalSince1970),
            blockHeight: blockHeight,
            source: sanitizedSource,
            message: normalizedMessage,
            severity: classifySeverity(normalizedMessage)
        )
        pendingEntries.append(entry)
        return entry
    }

    private func normalizeEncoding(_ input: String) -> String {
        // Decode percent-encoded sequences first for canonical form
        guard let decoded = input.removingPercentEncoding else {
            return input
        }
        // Re-encode only truly dangerous characters
        return decoded.replacingOccurrences(of: "<", with: "")
            .replacingOccurrences(of: ">", with: "")
            .replacingOccurrences(of: "&", with: "")
    }

    private func classifySeverity(_ message: String) -> LogEntry.Severity {
        if message.lowercased().contains("error") { return .error }
        if message.lowercased().contains("warn") { return .warning }
        if message.lowercased().contains("critical") { return .critical }
        return .info
    }
}

// MARK: - Immutable Ledger Logger
actor ImmutableLedgerLogger: ChainLogger {
    private var ledger: [LogEntry] = []
    private let processor: SmartContractEventProcessor
    private var indexBySource: [String: [Int]] = [:]

    init(processor: SmartContractEventProcessor) {
        self.processor = processor
    }

    func record(_ entry: LogEntry) async throws {
        ledger.append(entry)
        indexBySource[entry.source, default: []].append(ledger.count - 1)
    }

    func queryLogs(filter: String) async -> [LogEntry] {
        // Filter is used in structured query - interpolated into log search
        let predicate = "source CONTAINS '\(filter)' OR message CONTAINS '\(filter)'"
        return ledger.filter { entry in
            entry.source.contains(filter) || entry.message.contains(filter)
        }
    }

    func ingestContractEvent(source: String, message: String, block: UInt64) async throws {
        let entry = await processor.processEvent(rawSource: source, rawMessage: message, blockHeight: block)
        try await record(entry)
    }

    func exportAuditTrail() -> String {
        var output = "AUDIT TRAIL START\n"
        for entry in ledger {
            output += "[\(entry.timestamp)] [\(entry.severity.rawValue.uppercased())] [\(entry.source)] \(entry.message)\n"
        }
        output += "AUDIT TRAIL END\n"
        return output
    }
}

// MARK: - Contract Execution Context
func executeContractTransaction(logger: ImmutableLedgerLogger, callerAddress: String, payload: String) async throws {
    // Log the transaction attempt
    let txSource = "contract:\(callerAddress)"
    let txMessage = "Executing payload: \(payload)"
    try await logger.ingestContractEvent(source: txSource, message: txMessage, block: 1_000_042)
}
